-- Offline migration creates only this authority table; normal startup adds
-- runtime targets, counters and control views afterwards. VARBINARY identity
-- and historical alias keys preserve exact ASCII bytes without PAD SPACE.
CREATE TABLE IF NOT EXISTS ordinary_messages(delivery_id VARCHAR(32) NULL UNIQUE,message_id VARCHAR(32) NOT NULL PRIMARY KEY,op_id VARBINARY(128) NOT NULL UNIQUE,channel_id VARCHAR(26) NOT NULL,thing_id VARCHAR(64) NULL,fingerprint VARCHAR(128) NULL,payload_blob LONGBLOB NOT NULL,payload_bytes BIGINT NOT NULL,has_payload TINYINT GENERATED ALWAYS AS (payload_bytes>0) STORED,usage_payload_bytes BIGINT NOT NULL DEFAULT 0,accepted_at BIGINT NOT NULL,expires_at BIGINT NULL,dedupe_until BIGINT NOT NULL,status VARCHAR(32) NOT NULL,updated_at BIGINT NOT NULL,pending_targets BIGINT NOT NULL DEFAULT 0,provider_accepted_count BIGINT NOT NULL DEFAULT 0,provider_failed_count BIGINT NOT NULL DEFAULT 0,provider_target_count BIGINT NOT NULL DEFAULT 0,private_enqueued_count BIGINT NOT NULL DEFAULT 0,private_rejected_count BIGINT NOT NULL DEFAULT 0,identity_state VARBINARY(32) NOT NULL DEFAULT 'live',historical_op VARBINARY(128) GENERATED ALWAYS AS (CASE WHEN identity_state='legacy_unverifiable' THEN CAST(LOWER(CONVERT(op_id USING utf8mb4)) AS BINARY) ELSE NULL END) STORED,UNIQUE KEY ordinary_historical_op(historical_op),CONSTRAINT ordinary_message_identity CHECK((identity_state='live' AND delivery_id IS NOT NULL AND fingerprint IS NOT NULL AND expires_at IS NOT NULL) OR (identity_state='legacy_unverifiable' AND delivery_id IS NULL AND fingerprint IS NULL AND expires_at IS NULL AND payload_bytes=0 AND OCTET_LENGTH(payload_blob)=0 AND BINARY status=_binary'historical_unverifiable' AND pending_targets=0 AND provider_target_count=0 AND private_enqueued_count=0 AND provider_accepted_count=0 AND provider_failed_count=0 AND private_rejected_count=0 AND usage_payload_bytes=0)),INDEX messages_retention(dedupe_until,op_id),INDEX messages_expiry(has_payload,expires_at,delivery_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
